<div class="cuy-chat" x-data="cuyAiChat(@js(['history' => route('chat.history'), 'send' => route('chat.send'), 'reset' => route('chat.reset')]))" @keydown.escape.window="close()">
    <button class="cuy-chat-launcher" type="button" x-ref="launcher" x-show="!open" @click="show()" aria-label="Buka percakapan Cuy-AI" aria-controls="cuy-chat-panel" :aria-expanded="open"><img src="{{ asset('images/nativecuy_icon_64x64.png') }}" alt="" width="44" height="44"><span>Tanya Cuy-AI<small>Bingung? Mulai di sini.</small></span><x-public-icon name="chat"/></button>
    <div class="cuy-chat-backdrop" x-show="open" x-cloak @click="close()" aria-hidden="true"></div>
    <section id="cuy-chat-panel" class="cuy-chat-panel" x-ref="panel" x-show="open" x-cloak x-transition.opacity.duration.180ms role="dialog" aria-modal="true" aria-labelledby="cuy-chat-title" @keydown="trap($event)">
        <header class="cuy-chat-header"><img src="{{ asset('images/nativecuy_icon_64x64.png') }}" width="44" height="44" alt=""><div><h2 id="cuy-chat-title" x-ref="heading" tabindex="-1">Cuy-AI</h2><p>Asisten NativeCuy</p></div><button type="button" class="cuy-chat-icon-button" aria-label="Mulai percakapan baru" title="Percakapan baru" @click="confirmReset = !confirmReset" :disabled="loading || historyLoading || !messages.length"><x-public-icon name="revision"/></button><button class="cuy-chat-icon-button" type="button" aria-label="Tutup chat" @click="close()"><x-admin-icon name="close"/></button></header>
        <div class="cuy-chat-reset" x-show="confirmReset" x-cloak><p>Hapus riwayat dan mulai percakapan baru?</p><div><button type="button" @click="confirmReset = false" :disabled="loading">Batal</button><button type="button" @click="resetChat()" :disabled="loading">Ya, mulai baru</button></div></div>
        <div class="cuy-chat-scroll" x-ref="scrollArea" :aria-busy="loading || historyLoading">
            <div class="cuy-chat-welcome" x-show="!messages.length && !pending && !historyLoading"><span class="cuy-chat-welcome-icon"><x-public-icon name="chat"/></span><h3>Halo, Cuy.<br>Mau dibantu apa?</h3><p>Tanya soal layanan, alur order, atau cara cek progres. Kita mulai dari sini.</p><div class="cuy-chat-suggestions">
                <button type="button" @click="quick('Layanan apa saja yang tersedia dan berapa harga awalnya?')" :disabled="loading"><x-public-icon name="services"/><span>Layanan & harga awal</span><x-admin-icon name="arrow"/></button>
                <button type="button" @click="quick('Bagaimana cara membuat order dan menentukan deadline?')" :disabled="loading"><x-public-icon name="brief"/><span>Cara order & deadline</span><x-admin-icon name="arrow"/></button>
                <a href="{{ route('order.trackSearch') }}"><x-public-icon name="progress"/><span>Cek progres orderku</span><x-admin-icon name="arrow"/></a>
            </div></div>
            <p class="cuy-chat-status" x-show="historyLoading" role="status">Membuka percakapan…</p>
            <div class="cuy-chat-messages" role="log" aria-live="polite" aria-relevant="additions" aria-label="Percakapan dengan Cuy-AI"><template x-for="(message, index) in messages" :key="index"><div class="cuy-chat-message" :class="message.role === 'user' ? 'is-user' : 'is-assistant'"><span class="cuy-chat-speaker" x-text="message.role === 'user' ? 'Kamu' : 'Cuy-AI'"></span><div class="cuy-chat-bubble" x-html="renderMessage(message.content)"></div></div></template></div>
            <div class="cuy-chat-message is-user" x-show="pending" x-cloak><span class="cuy-chat-speaker">Kamu</span><div class="cuy-chat-bubble" x-text="pending"></div></div>
            <p class="cuy-chat-status" x-show="loading && pending" role="status"><span class="cuy-chat-typing" aria-hidden="true"><i></i><i></i><i></i></span>Cuy-AI sedang menyiapkan jawaban…</p>
        </div>
        <div class="cuy-chat-error" x-show="error" x-cloak role="alert"><p x-text="error"></p><button type="button" @click="draft.trim() ? send() : loadHistory()" :disabled="loading || historyLoading">Coba lagi</button></div>
        <div class="cuy-chat-compose"><form @submit.prevent="send()"><label class="sr-only" for="cuy-chat-input">Pertanyaan untuk Cuy-AI</label><textarea id="cuy-chat-input" x-ref="input" x-model="draft" @input="resizeInput()" @keydown="keydown($event)" rows="1" maxlength="1000" :disabled="loading || historyLoading" placeholder="Ceritakan kebutuhanmu…"></textarea><button type="submit" aria-label="Kirim pesan" :disabled="loading || historyLoading || !draft.trim()"><x-public-icon name="send"/></button></form><div class="cuy-chat-compose-meta"><span x-text="draft.length ? draft.length + '/1.000' : 'Enter untuk kirim · Shift+Enter baris baru'"></span></div><p class="cuy-chat-disclaimer">Jawaban AI bisa keliru. Harga dan deadline dikonfirmasi admin.</p></div>
        <a class="cuy-chat-admin" href="https://wa.me/{{ $publicContact['wa_number'] }}?text={{ urlencode('Halo NativeCuy, saya ingin konsultasi.') }}" target="_blank" rel="noopener noreferrer"><x-public-icon name="headset"/><span>Lebih nyaman ngobrol langsung?<strong>Chat admin via WhatsApp</strong></span><x-admin-icon name="external"/></a>
    </section>
</div>
